import type { DatabaseProfile } from "@/lib/profile/types";
import type { Exchange, Hypothesis } from "@/lib/hypotheses/schema";

/**
 * In development the static site (:3000) and the Worker (:8787) are separate
 * origins; in production they are the same origin, so this is empty.
 */
const API_BASE = process.env.NEXT_PUBLIC_API_BASE ?? "";

/**
 * Deliberately longer than the Worker's own 300s deadline.
 *
 * Inference here regularly takes one to two minutes, and `fetch` has no default
 * timeout at all, so without this a hung request would spin forever. Giving the
 * client extra headroom means the Worker's specific 504 usually arrives first
 * and the user sees a real explanation rather than a generic client-side abort;
 * this is the backstop for the Worker itself never answering.
 *
 * Cloudflare keeps the Worker alive only while the client stays connected, so
 * hanging up early would also kill the inference that is still running.
 */
export const CLIENT_TIMEOUT_MS = 330_000;

export interface HypothesesResponse {
  hypotheses: Hypothesis[];
  /** Verbatim record of the single exchange, for the user to inspect. */
  exchange: Exchange;
}

export class RequestTimeoutError extends Error {}

/** Abort when either the caller's signal or our deadline fires. */
function withDeadline(signal: AbortSignal | undefined, ms: number): AbortSignal {
  const deadline = AbortSignal.timeout(ms);
  if (!signal) return deadline;
  // AbortSignal.any is widely available; fall back to the deadline alone.
  return typeof AbortSignal.any === "function"
    ? AbortSignal.any([signal, deadline])
    : deadline;
}

export async function requestHypotheses(
  profile: DatabaseProfile,
  signal?: AbortSignal,
): Promise<HypothesesResponse> {
  let res: Response;
  try {
    res = await fetch(`${API_BASE}/api/hypotheses`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ profile }),
      signal: withDeadline(signal, CLIENT_TIMEOUT_MS),
    });
  } catch (err) {
    // A caller-initiated cancel should stay a cancel, not become a timeout.
    if (signal?.aborted) throw err;
    if (err instanceof Error && (err.name === "TimeoutError" || err.name === "AbortError")) {
      throw new RequestTimeoutError(
        `No response after ${Math.round(CLIENT_TIMEOUT_MS / 1000)}s. The model may still be working — try again, or use fewer tables.`,
      );
    }
    throw err;
  }

  if (!res.ok) {
    const body = await res.json().catch(() => null) as { error?: string } | null;
    const message = body?.error ?? `Request failed with ${res.status}.`;
    if (res.status === 504) throw new RequestTimeoutError(message);
    throw new Error(message);
  }

  return res.json();
}
