describe("timeout configuration", () => {
  it("allows long enough for real inference but is still bounded", () => {
    // Observed runs are 60-110s and the tail goes past two minutes, so a limit
    // under that would kill healthy requests.
    expect(PER_ATTEMPT_TIMEOUT_MS).toBeGreaterThanOrEqual(150_000);
    // The SDK default is 10 minutes AND retries timeouts. Ours must be tighter.
    expect(PER_ATTEMPT_TIMEOUT_MS).toBeLessThan(600_000);
    // The total must exceed one attempt, or retries could never happen...
    expect(TOTAL_DEADLINE_MS).toBeGreaterThan(PER_ATTEMPT_TIMEOUT_MS);
    // ...but must be far below attempts x per-attempt, which is the unbounded
    // worst case the deadline exists to prevent.
    expect(TOTAL_DEADLINE_MS).toBeLessThan(PER_ATTEMPT_TIMEOUT_MS * (MAX_RETRIES + 1));
