describe("client-side deadline", () => {
  const original = globalThis.fetch;
  const restore = () => { globalThis.fetch = original; };

  it("outlasts the Worker deadline so the server's explanation wins", () => {
    // If the client gave up first the user would see a generic abort instead of
    // the Worker's specific 504 — and hanging up also kills the inference,
    // because Cloudflare only keeps the Worker alive while the client is there.
    expect(CLIENT_TIMEOUT_MS).toBeGreaterThan(TOTAL_DEADLINE_MS);
  });

  it("surfaces a Worker 504 as a typed timeout with its message", async () => {
    globalThis.fetch = (async () =>
      new Response(JSON.stringify({ error: "The model did not respond within 300s.", timeout: true }), {
        status: 504, headers: { "content-type": "application/json" },
      })) as typeof fetch;
    try {
      await expect(requestHypotheses(profile)).rejects.toThrow(/did not respond within/);
      await expect(requestHypotheses(profile)).rejects.toBeInstanceOf(RequestTimeoutError);
    } finally { restore(); }
  });

  it("explains a client-side timeout rather than leaking AbortError", async () => {
    globalThis.fetch = (async () => {
      throw Object.assign(new Error("signal timed out"), { name: "TimeoutError" });
    }) as typeof fetch;
    try {
      await expect(requestHypotheses(profile)).rejects.toBeInstanceOf(RequestTimeoutError);
      await expect(requestHypotheses(profile)).rejects.toThrow(/may still be working/);
    } finally { restore(); }
  });

  it("keeps a caller-initiated cancel a cancel, not a timeout", async () => {
    const controller = new AbortController();
    controller.abort();
    globalThis.fetch = (async () => {
      throw Object.assign(new Error("aborted"), { name: "AbortError" });
    }) as typeof fetch;
    try {
      await expect(
        requestHypotheses(profile, controller.signal),
      ).rejects.not.toBeInstanceOf(RequestTimeoutError);
    } finally { restore(); }
  });

  it("passes other server errors through untouched", async () => {
    globalThis.fetch = (async () =>
      new Response(JSON.stringify({ error: "Anthropic rejected the API key." }), {
        status: 502, headers: { "content-type": "application/json" },
      })) as typeof fetch;
    try {
      await expect(requestHypotheses(profile)).rejects.toThrow(/rejected the API key/);
      await expect(requestHypotheses(profile)).rejects.not.toBeInstanceOf(RequestTimeoutError);
    } finally { restore(); }
  });
});
