  const viewRef = useRef<EditorView | null>(null);

  useEffect(() => {
    const mq = window.matchMedia("(prefers-color-scheme: dark)");
    setDark(mq.matches);
    const onChange = (e: MediaQueryListEvent) => setDark(e.matches);
    mq.addEventListener("change", onChange);
    return () => mq.removeEventListener("change", onChange);
  }, []);''',
'''  // Read once at mount rather than assigning inside an effect, which would
  // render light first and then immediately re-render dark.
  const [dark, setDark] = useState(
    () => window.matchMedia("(prefers-color-scheme: dark)").matches,
  );
  const viewRef = useRef<EditorView | null>(null);

  useEffect(() => {
    const mq = window.matchMedia("(prefers-color-scheme: dark)");
    const onChange = (e: MediaQueryListEvent) => setDark(e.matches);
    mq.addEventListener("change", onChange);
    return () => mq.removeEventListener("change", onChange);
  }, []);''')

# 2. db arrives through a getter, so the parent never reads a ref while rendering.
s = s.replace('''  open, onClose, db, loaded, ranQueries,
